include <robotics.scad>
// VLP-16 lower housing band. Origin: centre of bottom (mounting) face.
D      = 103.3;   // body diameter (datasheet)
H      = 18.8;    // lower band height (datasheet)
tap_d  = 5.1;     // 1/4-20 tap drill (#7); thread not modelled
tap_dp = 7.1;     // 9/32 in (datasheet)
pin_d  = 4.06;    // Ø0.16 in (datasheet)
pin_dp = 5.5;     // 7/32 in (datasheet)
pin_sp = 88.9;    // 3.50 in (datasheet)
gl_d   = 12.7;    // gland max width (datasheet)
gl_z   = 9.4;     // gland axis height: NOT dimensioned, mid-band
$fn = 128;
difference() {
  cyl(d = D, h = H, anchor = BOT);
  // 1/4-20 centre mount
  down(0.01) cyl(d = tap_d, h = tap_dp + 0.01, anchor = BOT, $fn = 32);
  // locating pin holes on the 90° axis (X)
  for (s = [-1, 1]) translate([s*pin_sp/2, 0, -0.01]) cyl(d = pin_d, h = pin_dp + 0.01, anchor = BOT, $fn = 32);
  // cable-gland seat at 0° (+Y)
  translate([0, D/2 - 3, gl_z]) ycyl(d = gl_d, h = 10, anchor = FRONT, $fn = 48);
}

include <robotics.scad>
// Optical window band. Origin: bottom of window (z = 18.8 in assembly).
D = 103.3; H = 38.1;
$fn = 128;
tube(od = D, id = D - 6, h = H, anchor = BOT);

include <robotics.scad>
// Top cap. Origin: bottom of cap (z = 56.9 in assembly).
D = 103.3; H = 71.7 - 18.8 - 38.1;  // 14.8
$fn = 128;
cyl(d = D, h = H, rounding2 = 1, anchor = BOT);

include <robotics.scad>
// Cable gland envelope. Origin: on the body surface (y = 51.65), gland axis along +Y.
d = 12.7; out = 12.7; seat = 3;
$fn = 48;
back(-seat) ycyl(d = d - 0.3, h = seat + 0.01, anchor = FRONT);          // shank in housing bore
ycyl(d = d, h = out, chamfer2 = 0.6, anchor = FRONT);                   // protruding body
